import sys
import os

def main():
    if len(sys.argv) < 2:
        print("")
        sys.exit(0)

    file_path = sys.argv[1]
    filename = os.path.basename(file_path)

    # Remove extension(s) - for .tar.gz style files
    name, ext = os.path.splitext(filename)
    if ext.lower() == '.gz':
        name2, ext2 = os.path.splitext(name)
        if ext2.lower() in ('.tar',):
            filename = name2
        else:
            filename = name
    elif ext.lower() == '.zip':
        name2, ext2 = os.path.splitext(name)
        if ext2.lower() in ('.tar',):
            filename = name2
        else:
            filename = name
    else:
        filename = name

    print(filename)
    sys.exit(0)

if __name__ == "__main__":
    main()

