def _b64decode(s, validate=False):
    if isinstance(s, (bytes, bytearray, memoryview)):
        data = bytes(s)
    else:
        raise TypeError("argument 1 must be a bytes-like object, not %s" % type(s).__name__)

    # Filter out whitespace characters
    import re as _re_mod
    cleaned = _re_mod.sub(rb'[\r\n\s]', b'', data)

    # Handle padding
    stripped = cleaned.rstrip(b'=')
    pad_count = len(cleaned) - len(stripped)

    if pad_count > 2:
        raise binascii.Error("Incorrect padding")

    if pad_count == 0:
        decoded_data = stripped
    elif pad_count == 1:
        # Invalid: need either 0 or at least the right number of chars
        # For base64, length should be multiple of 4 after adding padding
        # Without padding, length mod 4 should be 2 or 3
        if len(stripped) % 4 == 0 or len(stripped) % 4 == 1:
            raise binascii.Error("Incorrect padding")
        decoded_data = stripped + b'=='
        if len(decoded_data) % 4 != 0:
            raise binascii.Error("Incorrect padding")
    elif pad_count == 2:
        if len(stripped) % 4 == 1:
            raise binascii.Error("Incorrect padding")
        decoded_data = stripped + b'='
        if len(decoded_data) % 4 != 0:
            raise binascii.Error("Incorrect padding")

    # Check for non-base64 characters
    valid_chars = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    for byte in decoded_data:
        if byte not in valid_chars and byte != ord('='):
            # If validate is true, raise error immediately
            if validate:
                raise binascii.Error("Non-base64 digit found")
            # Otherwise, in some implementations it might still fail or produce garbage
            # CPython's b64decode without validate will also raise for invalid chars
            raise binascii.Error("Non-base64 digit found")

    # Check padding position
    for i, byte in enumerate(decoded_data):
        if byte == ord('='):
            # All remaining must also be =
            for j in range(i+1, len(decoded_data)):
                if decoded_data[j] != ord('='):
                    raise binascii.Error("Invalid base64 string")
            break

    # Now actually decode
    return binascii.a2b_base64(decoded_data)


