def _b64decode(s, altchars=None, validate=False):
    if isinstance(s, str):
        s = s.encode('latin-1')
    elif not isinstance(s, (bytes, bytearray, memoryview)):
        raise TypeError("argument should be a bytes-like object")
    else:
        s = bytes(s)

    if altchars:
        if len(altchars) != 2:
            raise ValueError("altchars must have length 2 or None")
        s = s.replace(altchars[0:1], b"+").replace(altchars[1:2], b"/")

    # Remove whitespace (always allowed by base64 module spec)
    filtered = []
    for c in s:
        if c < 32 or c == 127:
            continue
        filtered.append(c)
    s = bytes(filtered)

    n = len(s)
    if n == 0:
        return b""
    if n % 4 != 0:
        raise ValueError("Incorrect padding")

    # Build decode table
    dtable = {}
    for i in range(64):
        dtable[B64CHARS[i]] = i

    result = bytearray()
    i = 0
    while i < n:
        chunk = s[i:i+4]
        if len(chunk) < 4:
            break

        # Count padding
        pad_count = 0
        if chunk[-1] == ord("="):
            pad_count += 1
        if pad_count > 0 and chunk[-2] == ord("="):
            pad_count += 1
        if pad_count > 0 and chunk[-3] == ord("="):
            pad_count += 1

        if pad_count >= 3:
            # "===X" is invalid per RFC but some implementations allow "===="
            # Actually "====" would mean all 4 are padding which is invalid
            if pad_count == 4:
                raise ValueError("Invalid padding")

        vals = []
        j = 0
        while j < 4:
            c = chunk[j]
            if c == ord("="):
                vals.append(-1)
            else:
                if c not in dtable:
                    if validate:
                        raise ValueError("Non-base64 digit found")
                    else:
                        raise ValueError("Non-base64 digit found")
                vals.append(dtable[c])
            j += 1

        # Validate: padding must only appear at the end
        for k in range(4):
            if vals[k] == -1:
                for m in range(k+1, 4):
                    if vals[m] != -1:
                        raise ValueError("Invalid padding")

        # Decode 4 values into 3 bytes
        if pad_count == 0:
            v = vals[0] << 18 | vals[1] << 12 | vals[2] << 6 | vals[3]
            result.extend([v >> 16, v >> 8 & 0xFF, v & 0xFF])
        elif pad_count == 1:
            v = vals[0] << 18 | vals[1] << 12 | vals[2] << 6
            result.extend([v >> 16, v >> 8 & 0xFF])
        elif pad_count == 2:
            v = vals[0] << 18 | vals[1] << 12
            result.extend([v >> 16])
        elif pad_count == 3:
            result.extend([vals[0] << 16 >> 16])  # Just one byte from first char... 
            # Actually this case shouldn't really happen with valid input
            pass

    return bytes(result)


