        if ord(c) >= ord('a') and ord(c) <= ord('z'):
            return ord(c) - ord('a') + 26
        if ord(c) >= ord('0') and ord(c) <= ord('9'):
            return ord(c) - ord('0') + 52
        if c == '+':
            return 62
        if c == '/':
            return 63
        raise binascii_error("Invalid character")

    result = bytearray()
    # Process in groups of 4
    for i in range(0, len(no_pad), 4):
