    if isinstance(s, str):
        s = s.encode('utf-8')

    standard = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

    result = []
    n = len(s)
    for i in range(0, n, 3):
        chunk = s[i:i+3]
