import json, datetime, pathlib, tempfile, os

def _recent_capture_note(path):
    try:
        with open(path, 'r') as f:
            lines = f.readlines()
    except (FileNotFoundError, OSError):
        return None

    cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=7)

    for line in reversed(lines):
        line = line.strip()
        if not line:
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            continue
        if record.get("kind") != "note":
            continue
        ts_str = record.get("ts", "")
        try:
            ts = datetime.datetime.strptime(ts_str, "%Y-%m-%dT%H:%M:%S.000Z").replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            continue
        if ts >= cutoff:
            return record.get("detail")

