import sys, json, tempfile, datetime, pathlib

def _recent_capture_note(path):
    try:
        with open(path) as f:
            lines = [line.strip() for line in f if line.strip()]
    except Exception:
        return "no capture log"

    notes = []
    for line in lines:
        try:
            obj = json.loads(line)
        except Exception:
            continue
        if obj.get("kind") == "note":
            notes.append(obj)

    if not notes:
        return "no notes"

    now = datetime.datetime.now(datetime.timezone.utc)
    cutoff = (now - datetime.timedelta(days=7)).strftime("%Y-%m-%dT%H:%M:%S.000Z")

    recent = [n for n in notes if n.get("ts", "") >= cutoff]
    if not recent:
        return "no recent notes"

    # Return the most recent one
    recent.sort(key=lambda x: x.get("ts", ""))
    last = recent[-1]
    return last.get("detail", "no detail")


