class Cli:
    @staticmethod
    def _recent_capture_note(path):
        try:
            p = pathlib.Path(path)
            if not p.exists():
                return None
            lines = p.read_text().strip().split("\n")
            notes = []
            for line in lines:
                if not line.strip():
                    continue
                obj = json.loads(line)
                if obj.get("kind") == "note":
                    notes.append(obj)
            if not notes:
                return None

            now = datetime.datetime.now(datetime.timezone.utc)
            cutoff = now - datetime.timedelta(days=7)

            for note in notes:
                ts_str = note.get("ts", "")
                try:
                    # Parse ISO format like 2024-01-01T12:00:00.000Z
                    ts_clean = ts_str.replace("Z", "+00:00")
                    ts_dt = datetime.datetime.fromisoformat(ts_clean)
                    if ts_dt.tzinfo is None:
                        ts_dt = ts_dt.replace(tzinfo=datetime.timezone.utc)
                    if ts_dt >= cutoff:
                        return note.get("detail", None)
                except Exception:
                    continue

            return None
        except Exception:
            return None


