def _stringio():
    class S:
        def __init__(self, initial=''):
            self._buf = initial
        def write(self, s):
            self._buf += s
            return len(s)
        def getvalue(self):
            return self._buf
    return S()

class _writer:
    QUOTE_NONE = 0
    QUOTE_MINIMAL = 1
    QUOTE_NONNUMERIC = 2
    QUOTE_ALL = 3

    @classmethod
    def writer(cls, f, quoting=cls.QUOTE_MINIMAL, delimiter=',', quotechar='"', doublequote=True, escapechar=None, lineterminator='\r\n'):
        w = cls(f, quoting, delimiter, quotechar, doublequote, escapechar, lineterminator)
        return w

    def __init__(self, f, quoting, delimiter, quotechar, doublequote, escapechar, lineterminator):
        self.f = f
        self.quoting = quoting
        self.delimiter = delimiter
        self.quotechar = quotechar
        self.doublequote = doublequote
        self.escapechar = escapechar
        self.lineterminator = lineterminator

    def write_row(self, row):
        fields = []
        for field in row:
            if isinstance(field, (list, tuple)):
                val = ','.join(str(x) for x in field)
            else:
                val = str(field)
            if self.quoting == self.QUOTE_ALL:
                quoted_val = self._quote(val)
                fields.append(quoted_val)
            elif self.quoting == self.QUOTE_NONNUMERIC:
                try:
                    float(val)
                    fields.append(val)
                except (ValueError, TypeError):
                    fields.append(self._quote(val))
            else:
                if (self.delimiter in val or self.quotechar in val or 
                    '\n' in val or '\r' in val):
                    fields.append(self._quote(val))
                else:
                    fields.append(val)
        line = self.delimiter.join(fields) + self.lineterminator
        self.f.write(line)

    def writeheader(self, header):
        self.write_row(header)

    def writerows(self, rows):
        for row in rows:
            self.write_row(row)

    def _quote(self, val):
        q = self.quotechar
        if self.escapechar is not None:
            # Escape characters using escapechar
            escaped = ''
            for ch in val:
                if ch == q:
                    escaped += self.escapechar + q
                elif ch == self.delimiter:
                    escaped += self.escapechar + ch
                elif ch in ('\r', '\n'):
                    escaped += self.escapechar + ch
                else:
                    escaped += ch
            return q + escaped + q
        elif self.doublequote:
            return q + val.replace(q, q+q) + q
        else:
            return q + val + q


