import json
import glob
import collections

c = collections.Counter()
ex = None

files = sorted(glob.glob('*.jsonl'))
for f in files:
    for l in open(f, errors='replace'):
        l = l.strip()
        if not l:
            continue
        try:
            o = json.loads(l)
        except Exception:
            continue
        m = o.get('message')
        if not isinstance(m, dict):
            continue
        ct = m.get('content')
        if not isinstance(ct, list):
            continue
        for b in ct:
            if isinstance(b, dict) and b.get('type') == 'tool_use' and b.get('name') == 'Bash':
                c[(o.get('type'), m.get('model'))] += 1
                if ex is None:
                    ex = {k: (v if k != 'content' else '...') for k, v in m.items()}

for k, v in c.most_common(20):
    print(v, k)
print("message keys on a tool_use record:", ex)

