class MBS(str):
    def __init__(self, s="", pos=0):
        super().__init__(s)
        self.pos = pos
    def read(self, size=-1):
        if size == -1:
            v = self[self.pos:]
            self.pos = len(self)
        else:
            v = self[self.pos:self.pos+size]
            self.pos += size
        return v
    def readline(self):
        i = self.find("\n", self.pos)
        if i < 0:
            v = self[self.pos:]
            self.pos = len(self)
        else:
            v = self[self.pos:i+1]
            self.pos = i+1
        return v

