def _sorted_tuple_order(a, b):
    ta = tuple(a)
    tb = tuple(b)
    if ta == tb:
        return 0
    if isinstance(ta, int) and not isinstance(tb, int):
        return -1
    if isinstance(tb, int) and not isinstance(ta, int):
        return 1
    if ta < tb:
        return -1
    return 1

