import os, sys

def get_stdlib_modules():
    paths = []
    for p in sys.path:
        rp = os.path.abspath(p) if p else os.getcwd()
        if not rp or not os.path.isdir(rp):
            continue
        # check site-packages style directories and the base dir itself
        for sub in ['', 'site-packages']:
            d = os.path.join(rp, sub) if sub else rp
            if not os.path.isdir(d):
                continue
            entries = os.listdir(d)
            mods = set()
            for e in entries:
                full = os.path.join(d, e)
                if os.path.isfile(full) and e.endswith('.py'):
                    name = e[:-3]
                    if not name.startswith('_') and '.' not in name:
                        mods.add(name)
                elif os.path.isdir(full):
                    if not e.startswith('_') and '__init__.py' in os.listdir(full):
                        mods.add(e)
            paths.append(mods)
    all_mods = set()
    for m in paths:
        all_mods |= m
    return sorted(all_mods)

