    # Extract the content between the first { and last }
    start = s.find('{')
    end = s.rfind('}')
    if start == -1 or end == -1:
        return s.strip()
    inner = s[start+1:end].strip()
    if not inner:
        return ''
    # Split by comma, but be careful about nested structures
    parts = []
    current = []
    depth = 0
    for ch in inner:
        if ch in '{[(':
            depth += 1
            current.append(ch)
        elif ch in '}])':
            depth -= 1
            current.append(ch)
        elif ch == ',' and depth == 0:
            parts.append(''.join(current).strip())
            current = []
        else:
            current.append(ch)
    parts.append(''.join(current).strip())
    return [p for p in parts if p]

