import sys

def only_set_order_differs(cp: str, mp: str) -> bool:
    """Check if two multi-line strings differ only by element order within sets."""
    cp_lines = cp.strip().split('\n') if cp.strip() else []
    mp_lines = mp.strip().split('\n') if mp.strip() else []

    if len(cp_lines) != len(mp_lines):
        return False

    for cp_line, mp_line in zip(cp_lines, mp_lines):
        # Parse each line as a Python set
        try:
            cp_set = eval(cp_line)
            mp_set = eval(mp_line)
        except Exception:
            return False

        if not isinstance(cp_set, set) or not isinstance(mp_set, set):
            return False

        if cp_set != mp_set:
            return False

    return True

