import os, sys

def _glob_expanduser_glob(pattern):
    """
    Replicate glob.glob(os.path.expanduser(pattern)) for the specific pattern
    ~/.claude/projects/*/*.jsonl using only os and builtins.
    Returns a sorted list of files to ensure deterministic output order.
    """
    pattern = os.path.expanduser(pattern)
    # pattern looks like: /path/.claude/projects/*/*.jsonl
    # Split into prefix, middle (wildcard dirs), suffix
    # The structure is: <base>/*/​<file>.jsonl where file contains *

    parts = pattern.split('*')
    # For our specific pattern, we expect 3 parts:
    # parts[0] = "/home/user/.claude/projects/"
    # parts[1] = "/"
    # parts[2] = ".jsonl"

    if len(parts) != 3:
        # Fallback for unexpected patterns - just return empty or handle simply
        return []

    base_dir = parts[0].rstrip('/\\')
    middle_sep = parts[1]
    suffix = parts[2]

    results = []

    try:
        # First level wildcard: directories inside base_dir
        entries = os.listdir(base_dir)
    except (OSError, FileNotFoundError, NotADirectoryError):
        return []

    for d in entries:
        dir_path = os.path.join(base_dir, d)
        if not os.path.isdir(dir_path):
            continue

        # Second level: files in each directory that match *.jsonl
        # We need to find files ending with suffix (.jsonl)
        try:
            sub_entries = os.listdir(dir_path)
        except (OSError, FileNotFoundError, NotADirectoryError):
            continue

        for fname in sub_entries:
            if fname.endswith(suffix):
                # Check if it's a regular file (or at least exists)
                full_path = os.path.join(dir_path, fname)
                if os.path.isfile(full_path):
                    results.append(full_path)

    return sorted(results)


def main():
    pattern = "~/.claude/projects/*/*.jsonl"
    fs = _glob_expanduser_glob(pattern)

    tsex = None
    side = 0
    tot = 0
    tu = 0
    withid = 0

    for f in fs:
        try:
            fh = open(f, 'r')
        except (IOError, OSError, PermissionError):
            continue
        try:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    import json
                    ev = json.loads(line)
                except Exception:
                    continue
                tot += 1
                if ev.get('isSidechain'):
                    side += 1
                if tsex is None and ev.get('timestamp'):
                    tsex = ev['timestamp']
                m = ev.get('message')
                if isinstance(m, dict) and isinstance(m.get('content'), list):
                    for b in m['content']:
                        if isinstance(b, dict) and b.get('type') == 'tool_use':
                            tu += 1
                            if b.get('id'):
                                withid += 1
        finally:
            fh.close()

    print("records", tot, "sidechain", side, "tool_use blocks", tu, "with id", withid)
    print("timestamp example:", tsex)


