def parse_json(value):
    """Minimal JSON parser using only built-in features."""
    value = value.strip()
    pos = 0

    def skip_ws():
        nonlocal pos
        while pos < len(value) and value[pos] in ' \t\n\r':
            pos += 1

    def parse_value():
        skip_ws()
        if pos >= len(value):
            raise ValueError('unexpected end')
        c = value[pos]
        if c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == '"':
            return parse_string()
        elif c == 't':
            expect('true'); return True
        elif c == 'f':
            expect('false'); return False
        elif c == 'n':
            expect('null'); return None
        else:
            return parse_number()

    def expect(s):
        nonlocal pos
        if not value.startswith(s, pos):
            raise ValueError('expected %s at %d' % (s, pos))
        pos += len(s)

    def parse_object():
        nonlocal pos
        pos += 1  # skip {
        result = {}
        skip_ws()
        if pos < len(value) and value[pos] == '}':
            pos += 1
            return result
        while True:
            skip_ws()
            key = parse_string()
            skip_ws()
            if pos >= len(value) or value[pos] != ':':
                raise ValueError('expected : at %d' % pos)
            pos += 1
            val = parse_value()
            result[key] = val
            skip_ws()
            if pos >= len(value):
                raise ValueError('unexpected end')
            if value[pos] == ',':
                pos += 1
                continue
            elif value[pos] == '}':
                pos += 1
                break
            else:
                raise ValueError('expected , or } at %d' % pos)
        return result

    def parse_array():
        nonlocal pos
        pos += 1  # skip [
        result = []
        skip_ws()
        if pos < len(value) and value[pos] == ']':
            pos += 1
            return result
        while True:
            item = parse_value()
            result.append(item)
            skip_ws()
            if pos >= len(value):
                raise ValueError('unexpected end')
            if value[pos] == ',':
                pos += 1
                continue
            elif value[pos] == ']':
                pos += 1
                break
            else:
                raise ValueError('expected , or ] at %d' % pos)
        return result

    def parse_string():
        nonlocal pos
        pos += 1  # skip opening quote
        chars = []
        while pos < len(value):
            c = value[pos]
            if c == '\\':
                pos += 1
                if pos >= len(value):
                    raise ValueError('unterminated escape')
                ec = value[pos]
                if ec == 'n':
                    chars.append('\n')
                elif ec == 't':
                    chars.append('\t')
                elif ec == 'r':
                    chars.append('\r')
                elif ec == 'b':
                    chars.append('\b')
                elif ec == 'f':
                    chars.append('\f')
                elif ec == '"':
                    chars.append('"')
                elif ec == '\\':
                    chars.append('\\')
                elif ec == '/':
                    chars.append('/')
                elif ec == 'u':
                    hex_str = value[pos+1:pos+5]
                    try:
                        code = int(hex_str, 16)
                        chars.append(chr(code))
                    except Exception:
                        raise ValueError('bad unicode escape')
                    pos += 4
                else:
                    raise ValueError('bad escape \\%c' % ec)
                pos += 1
            elif c == '"':
                pos += 1
                break
            else:
                chars.append(c)
                pos += 1
        return ''.join(chars)

    def parse_number():
        nonlocal pos
        start = pos
        while pos < len(value) and value[pos] in '-+0123456789.eE':
            pos += 1
        s = value[start:pos]
        if '.' in s or 'e' in s or 'E' in s:
            return float(s)
        return int(s)

    result = parse_value()
    skip_ws()
    if pos != len(value):
        raise ValueError('trailing data at %d' % pos)
    return result


