def json_loads(s):
    # Try to parse a JSON string. We only need top-level object with keys.
    s = s.strip()
    if not (s.startswith('{') and s.endswith('}')):
        raise ValueError('not a json object')
    inner = s[1:-1]
    if not inner.strip():
        return {}
    # Simple parser for flat objects with string keys/values including nested arrays/objects
    result = {}
    i = 0
    n = len(inner)
    while i < n:
        # skip whitespace
        while i < n and inner[i] in ' \t\r\n':
            i += 1
        if i >= n:
            break
        if inner[i] == '}':
            i += 1
            continue
        # read key
        if inner[i] != '"':
            raise ValueError('expected key')
        j = i + 1
        key_chars = []
        while j < n:
            c = inner[j]
            if c == '\\' and j + 1 < n:
                key_chars.append(inner[j + 1])
                j += 2
            elif c == '"':
                break
            else:
                key_chars.append(c)
                j += 1
        key = ''.join(key_chars)
        i = j + 1
        # skip whitespace
        while i < n and inner[i] in ' \t\r\n':
            i += 1
        if i >= n or inner[i] != ':':
            raise ValueError('expected colon')
        i += 1
        # skip whitespace
        while i < n and inner[i] in ' \t\r\n':
            i += 1
        # read value
        val, i = read_value(inner, i)
        result[key] = val
        # skip whitespace
        while i < n and inner[i] in ' \t\r\n':
            i += 1
        if i < n:
            if inner[i] == ',':
                i += 1
            elif inner[i] == '}':
                i += 1
                break
            else:
                raise ValueError('unexpected char after value')
    return result


def read_value(s, i):
    n = len(s)
    if i >= n:
        raise ValueError('unexpected end')
    c = s[i]
    if c == '{':
        depth = 0
        j = i
        while j < n:
            cc = s[j]
            if cc == '"' :
                j += 1
                while j < n:
                    if s[j] == '\\':
                        j += 2
                        continue
                    if s[j] == '"':
                        break
                    j += 1
            else:
                if cc == '{':
                    depth += 1
                elif cc == '}':
                    depth -= 1
                    if depth == 0:
                        return s[i:j+1], j+1
            j += 1
        raise ValueError('unbalanced {')
    elif c == '[':
        depth = 0
        j = i
        while j < n:
            cc = s[j]
            if cc == '"':
                j += 1
                while j < n:
                    if s[j] == '\\':
                        j += 2
                        continue
                    if s[j] == '"':
                        break
                    j += 1
            else:
                if cc == '[':
                    depth += 1
                elif cc == ']':
                    depth -= 1
                    if depth == 0:
                        return s[i:j+1], j+1
            j += 1
        raise ValueError('unbalanced [')
    elif c == '"':
        j = i + 1
        chars = []
        while j < n:
            ch = s[j]
            if ch == '\\' and j + 1 < n:
                next_ch = s[j+1]
                if next_ch == 'n':
                    chars.append('\n')
                elif next_ch == 't':
                    chars.append('\t')
                elif next_ch == 'r':
                    chars.append('\r')
                elif next_ch == '"':
                    chars.append('"')
                elif next_ch == '\\':
                    chars.append('\\')
                elif next_ch == '/':
                    chars.append('/')
                elif next_ch == 'b':
                    chars.append('\b')
                elif next_ch == 'f':
                    chars.append('\f')
                else:
                    chars.append(next_ch)
                j += 2
            elif ch == '"':
                break
            else:
                chars.append(ch)
                j += 1
        return ''.join(chars), j+1
    else:
        j = i
        while j < n and s[j] not in ',}] \t\r\n':
            j += 1
        token = s[i:j].strip()
        if token == 'true':
            return True, j
        elif token == 'false':
            return False, j
        elif token == 'null':
            return None, j
        else:
            try:
                if '.' in token or 'e' in token.lower():
                    return float(token), j
                else:
                    return int(token), j
            except ValueError:
                raise ValueError('bad number: '+token)


