import json, os

def list_files(pattern):
    """Find files matching pattern without glob module.

    Supports patterns like ~/*/*/*.jsonl by walking directories.
    Returns a sorted list of file paths.
    """
    # Expand user in pattern
    pattern = os.path.expanduser(pattern)

    # Parse the pattern: split on wildcards
    # The pattern is ~/.claude/projects/*/*.jsonl
    parts = pattern.split('/')

    # Find where wildcards start
    fixed_parts = []
    wildcard_start = None

    for i, part in enumerate(parts):
        if '*' in part:
            wildcard_start = i
            break
        fixed_parts.append(part)

    if wildcard_start is None:
        # No wildcards, just check if it's a file
        if os.path.isfile(pattern):
            return [pattern]
        return []

    # Build the base path from fixed parts
    base_path = '/'.join(fixed_parts) if fixed_parts else '/'
    if not base_path:
        base_path = '/'

    # The remaining parts after wildcard_start form the template
    remaining_parts = parts[wildcard_start:]

    results = set()

    # Walk through directories under base_path
    try:
        entries = os.listdir(base_path)
    except OSError:
        return []

    # Match each entry against the remaining parts
    def match_pattern(path_prefix, path_components, component_index):
        """Recursively match path components against pattern."""
        if component_index >= len(path_components):
            # All pattern components matched; check if final path exists and matches last component exactly
            full_path = path_prefix
            # Last component must be exact match (it had no wildcard in our case)
            if os.path.isfile(full_path):
                results.add(full_path)
            return

        current_component = path_components[component_index]

        try:
            dir_entries = os.listdir(path_prefix)
        except OSError:
            return

        for entry in dir_entries:
            new_prefix = os.path.join(path_prefix, entry)

            # Check if entry matches current_component
            if match_single(entry, current_component):
                if component_index < len(path_components) - 1:
                    # Not last component, must be a directory
                    if os.path.isdir(new_prefix):
                        match_pattern(new_prefix, path_components, component_index + 1)
                else:
                    # Last component, must be a file
                    if os.path.isfile(new_prefix):
                        results.add(new_prefix)

    match_pattern(base_path, remaining_parts, 0)

    return sorted(results)


def match_single(name, pattern):
    """Match a single filename against a simple pattern with *."""
    # Simple implementation for patterns with *
    import re as _re
    # Escape regex special chars except *, then convert * to .*, ? to .
    escaped = ''
    for c in pattern:
        if c == '*':
            escaped += '.*'
        elif c == '?':
            escaped += '.'
        else:
            escaped += _re.escape(c)
    # Use fullmatch
    try:
        m = _re.match('^' + escaped + '$', name)
        return bool(m)
    except Exception:
        return False


