def _matches(name, pattern):
    """Match string against pattern with * and ? only."""
    n_len = len(name)
    p_len = len(pattern)
    i = 0
    j = 0
    star_i = -1
    star_j = -1
    while i < n_len:
        if j < p_len and (pattern[j] == '?' or pattern[j] == name[i]):
            i += 1
            j += 1
        elif j < p_len and pattern[j] == '*':
            star_i = i
            star_j = j
            j += 1
        elif star_j != -1:
            star_j += 1
            j = star_j
            i = star_i + 1
        else:
            return False
    while j < p_len and pattern[j] == '*':
        j += 1
    return j == p_len


