def parse_number(s):
    sign = 1.0
    i = 0
    n = len(s)
    if i < n and s[i] == '-':
        sign = -1.0
        i += 1
    elif i < n and s[i] == '+':
        i += 1
    intpart = ''
    while i < n and s[i].isdigit():
        intpart += s[i]
        i += 1
    fracpart = ''
    if i < n and s[i] == '.':
        i += 1
        while i < n and s[i].isdigit():
            fracpart += s[i]
            i += 1
    expval = 0
    has_exp = False
    if i < n and (s[i] == 'e' or s[i] == 'E'):
        has_exp = True
        i += 1
        expsign = 1
        if i < n and (s[i] == '+' or s[i] == '-'):
            if s[i] == '-':
                expsign = -1
            i += 1
        expdigits = ''
        while i < n and s[i].isdigit():
            expdigits += s[i]
            i += 1
        if expdigits:
            expval = expsign * int(expdigits)
    val = 0.0
    if intpart:
        val = float(intpart)
    if fracpart:
        val += float('0.' + fracpart)
    if not intpart and not fracpart:
        val = 0.0
    if has_exp:
        val *= 10.0 ** expval
    return sign * val


