class MT:
    def __init__(self, seed):
        self.mt = [0] * 624
        self.index = 624
        self.mt[0] = seed & 0xFFFFFFFF
        for i in range(1, 624):
            x = self.mt[i - 1] ^ (self.mt[i - 1] >> 30)
            self.mt[i] = (1812433253 * x + i) & 0xFFFFFFFF
        self.generate()

    def generate(self):
        mt = self.mt
        for i in range(624):
            x = (mt[i] & 0x80000000) + (mt[(i + 1) % 624] & 0xFFFF)
            if i == 0:
                x = (mt[i] & 0x80000000) + (mt[1] & 0xFFFF)
            elif i == 623:
                x = (mt[i] & 0x80000000) + (mt[0] & 0xFFFF)
            else:
                x = (mt[i] & 0x80000000) + (mt[i + 1] & 0xFFFF)
            mt[i] = mt[i & 0x1FF] ^ (x >> 1) ^ (-((x & 1)) << 31) & 0xFFFFFFFF
        self.index = 0

    def next_int(self):
        if self.index >= 624:
            self.generate()
        mt = self.mt
        y = mt[self.index]
        self.index += 1
        y ^= (y >> 11)
        y ^= (y << 7) & 2636928640
        y ^= (y << 15) & 4022730752
        y ^= (y >> 18)
        return y

def random_randrange_with_step(start, stop, step, rng):
    # Compute len(range(start, stop, step))
    if step > 0:
        count = max(0, (stop - start + step - 1) // step)
    else:
        count = max(0, (start - stop - step - 1) // (-step))

    if count <= 0:
        raise ValueError("empty range")

    if count == 1:
        return start

    # Use getrandbits to get a uniform integer in [0, count)
    # Find bits needed
    k = count.bit_length()
    while True:
        val = rng.next_int() >> (32 - k)
        if val < count:
            break

    return start + val * step

