        for i in range(624):
            y = (self.mt[i] & 0x80000000) + (self.mt[(i+1) % 624] & 0x7FFFFFFF)
            self.mt[i] = self.mt[(i+397) % 624] ^ (y >> 1)
            if y % 2 != 0:
                self.mt[i] ^= 2567483615

    def getrandombits(self):
        if self.index >= 624:
            self.generate_numbers()
            self.index = 0
        x = self.mt[self.index]
        self.index += 1
        x ^= x >> 11
        x ^= (x << 7) & 2636928640
        x ^= (x << 15) & 4022730752
        x ^= x >> 18
        return x

    def randrange(self, start, stop, step=1):
        # Replicate CPython _randbelow_int algorithm
        width = stop - start
        if step < 0:
            raise ValueError("step must be positive")
        if step == 1 and width > 0:
            return self._randbelow(width) + start
        else:
            n = (stop - start - 1) // step
            return self._randbelow(n + 1) * step + start

    def _randbelow(self, n):
        # Same as CPython random._randbelow
        getrandbits = self.getrandombits
        k = n.bit_length()
        r = getrandbits(k)
        if r < n:
            return r
        while True:
            mask = (1 << k) - 1
            r &= mask
            if r < n:
                return r
            r = getrandbits(k)


