def safe_percent_format(fmt, val):
    # Check if fmt matches patterns with precision on integer conversions
    # Patterns: [flags][width].[precision]conversion where conversion in diouxXeEfgGcs
    import re
    m = re.match(r'^([-+0 ]*)(\d*)\.(\d*)([diouxXeEfgGcs])$', fmt)
    if m and m.group(4) in 'diouxX':
