        # Replicate what CPython does: precision is min digits
        sign = ''
        conv = m.group(4)
        prec = int(m.group(3))
        flags = m.group(1)
        width_str = m.group(2)

        if conv == 'd' or conv == 'i':
            s = str(val)
            if s.startswith('-'):
                sign = '-'
                s = s[1:]
            # Pad with zeros to at least prec digits
            s = s.zfill(prec)
            s = sign + s
            # Apply width/flags
            total_width = int(width_str) if width_str else len(s)
            if '+' in flags and val >= 0:
                s = '+' + s
                total_width += 1
            elif ' ' in flags and val >= 0:
                s = ' ' + s
                total_width += 1

            if '0' in flags:
                pad_char = '0'
            elif '-' in flags:
                s = s.ljust(total_width)
                return repr(s)
            else:
                pad_char = ' '

            if '-' not in flags:
                s = s.rjust(total_width, pad_char)

            return repr(s)

    # Otherwise, use normal percent formatting
    return repr(fmt % val)

