def unicode_repr(s):
    """Return repr() of a string without using the builtin repr()."""
    result = ["'"]
    for c in s:
        o = ord(c)
        if c == "'":
            result.append("\\'")
        elif c == "\\":
            result.append("\\\\")
        elif c == "\n":
            result.append("\\n")
        elif c == "\t":
            result.append("\\t")
        elif c == "\r":
            result.append("\\r")
        elif c == "\f":
            result.append("\\f")
        elif c == "\v":
            result.append("\\v")
        elif 32 <= o <= 126 and c not in ("'", "\\"):
            result.append(c)
        else:
            # For non-ASCII or other control chars, use \x or \u escape
            if o < 0x20 or o > 0x7e:
                if o <= 0xff:
                    result.append("\\x%02x" % o)
                else:
                    result.append("\\u%04x" % o)
            else:
                # Should not reach here given conditions above
                result.append(c)
    result.append("'")
    return "".join(result)


