            i += 1
            continue

        if c in ('"', "'"):
            in_string = True
            string_char = c
            current += c
            i += 1
            continue

        if c == '(':
            depth += 1
            current += c
            i += 1
            continue

        if c == ')':
            depth -= 1
            if depth == 0:
                # End of this argument set
                args.append(_eval_arg(current.strip()))
                return args
            current += c
            i += 1
            continue

        if c == ',' and depth == 0:
            args.append(_eval_arg(current.strip()))
            current = ''
            i += 1
            continue

        current += c
        i += 1

    if current.strip():
        args.append(_eval_arg(current.strip()))
    return args


def _eval_arg(arg):
    """Evaluate a single argument which may be a string literal, number, lambda, or identifier."""
    arg = arg.strip()
    if not arg:
        raise ValueError("empty argument")

    # Check for raw string literal
    if arg.startswith('r"') and arg.endswith('"') and not arg.endswith('\\\\"'):
        return arg[2:-1]
    if arg.startswith("r'") and arg.endswith("'") and not arg.endswith("\\\\'"):
        return arg[2:-1]

    # Check for regular string literal with double quotes
    if arg.startswith('"') and arg.endswith('"') and len(arg) >= 2:
        inner = arg[1:-1]
        return _unescape(inner, '"')

    # Check for regular string literal with single quotes
    if arg.startswith("'") and arg.endswith("'") and len(arg) >= 2:
        inner = arg[1:-1]
        return _unescape(inner, "'")

    # Lambda
    if arg.startswith('lambda '):
        return _make_lambda(arg)

    # Number
    try:
        return int(arg)
    except ValueError:
        pass

    try:
        return float(arg)
    except ValueError:
        pass

    # Identifier - shouldn't happen in our use cases
    raise ValueError("cannot evaluate argument: %r" % arg)


def _unescape(s, quote_char):
    """Unescape a Python string body (without the outer quotes)."""
    result = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '\\' and i + 1 < n:
            nc = s[i+1]
            if nc == 'n':
                result.append('\n')
                i += 2
                continue
            elif nc == 't':
                result.append('\t')
                i += 2
                continue
            elif nc == 'r':
                result.append('\r')
                i += 2
                continue
            elif nc == '\\':
                result.append('\\')
                i += 2
                continue
            elif nc == "'":
                result.append("'")
                i += 2
                continue
            elif nc == '"':
                result.append('"')
                i += 2
                continue
            elif nc == '0':
                result.append('\0')
                i += 2
                continue
            elif nc.isdigit() and nc >= '0' and nc <= '7':
                # Octal escape
                oct_digits = nc
                j = i + 2
                while j < n and j < i + 4 and s[j].isdigit() and s[j] <= '7':
                    oct_digits += s[j]
                    j += 1
                result.append(chr(int(oct_digits, 8)))
                i = j
                continue
            elif nc == 'x':
                if i + 3 < n:
                    hex_digits = s[i+2:i+4]
                    result.append(chr(int(hex_digits, 16)))
                    i += 4
                    continue
            elif nc == 'u':
                if i + 5 < n:
                    hex_digits = s[i+2:i+6]
                    result.append(chr(int(hex_digits, 16)))
                    i += 6
                    continue
            elif nc == 'N':
                # \N{...} - Unicode named character
                j = s.index('}', i)
                name = s[i+2:j]
                # Handle common ones
                unicode_names = {
                    'LINE SEPARATOR': '\u2028',
                    'PARAGRAPH SEPARATOR': '\u2029',
                }
                result.append(unicode_names.get(name, '\ufffd'))
                i = j + 1
                continue
            else:
                result.append(nc)
                i += 2
                continue
        else:
            result.append(c)
            i += 1

    return ''.join(result)


