def _ast_eval(node, vars_dict):
    import ast

    if isinstance(node, ast.Name):
        if node.id in vars_dict:
            return vars_dict[node.id]
        raise NameError(node.id)
    elif isinstance(node, ast.Call):
        func = _ast_eval(node.func, vars_dict)
        args = [_ast_eval(a, vars_dict) for a in node.args]
        return func(*args)
    elif isinstance(node, ast.Attribute):
        obj = _ast_eval(node.value, vars_dict)
        return getattr(obj, node.attr)
    elif isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Num):  # Python < 3.8 compatibility
        return node.n
    elif isinstance(node, ast.Str):  # Python < 3.8 compatibility
        return node.s
    else:
        raise ValueError("unsupported AST node: %s" % type(node).__name__)


