def custom_repr(s):
    # Reproduce Python's repr() for str without using repr()
    if not s:
        return "''"

    # We need to decide between single and double quotes.
    # Python prefers single quotes unless the string contains unescaped single quotes.
    # If it contains both, it uses whichever requires fewer escapes, preferring single on ties? 
    # Actually CPython: it checks which quote needs fewer backslashes. If tie, use single.

    def count_escapes(quote_char):
        count = 0
        for c in s:
            o = ord(c)
            if c == '\\' or c == quote_char:
                count += 1
            elif o < 32 or o >= 127:
                # Non-printable or non-ASCII needs escape
                # But wait, in normal repr(), printable ASCII (32-126) is shown as-is.
                # Control chars and non-ASCII are escaped with \x, \u, etc.
                # So they don't add a backslash in our count for this purpose - they're always escaped regardless of quote type.
                # Actually the choice of quote only affects whether ' or " need escaping.
                pass
        return count

    single_escapes = count_escapes("'")
    double_escapes = count_escapes('"')

    # CPython logic: use single quote if there are no unescaped single quotes or if singles have fewer/equal escapes
    if "'" not in s or single_escapes <= double_escapes:
        quote = "'"
    else:
        quote = '"'

    result = []
    for c in s:
        o = ord(c)
        if c == '\\':
            result.append('\\\\')
        elif c == quote:
            result.append('\\' + c)
        elif o < 32 or o >= 127:
            # For control characters:
            if o == 0x08:
                result.append('\\b')
            elif o == 0x09:
                result.append('\\t')
            elif o == 0x0a:
                result.append('\\n')
            elif o == 0x0b:
                result.append('\\v')
            elif o == 0x0c:
                result.append('\\f')
            elif o == 0x0d:
                result.append('\\r')
            elif o < 0x20 or o == 0x7f:
                result.append('\\x%02x' % o)
            else:
