                if o > 0xffff:
                    # Surrogate pair representation
                    o -= 0x10000
                    hi = 0xd800 + (o >> 10)
                    lo = 0xdc00 + (o & 0x3ff)
                    result.append('\\U%08x' % ord(c))
                else:
                    result.append('\\u%04x' % o)
        else:
            result.append(c)

    return quote + ''.join(result) + quote


