def ascii_repr(s):
    if not isinstance(s, str):
        return repr(s)
    out = []
    for c in s:
        o = ord(c)
        if o < 32 or o == 127:
            out.append("\\x%02x" % o)
        elif c == "\\":
            out.append("\\\\")
        elif c == "'":
            out.append("\\'")
        elif o > 126:
            # For non-ASCII, use \uXXXX format if <= 0xFFFF else \UXXXXXXXX
            if o <= 0xFFFF:
                out.append("\\u%04x" % o)
            else:
                out.append("\\U%08x" % o)
        else:
            out.append(c)
    # Now we need to produce a string that looks like repr output with single quotes
    # but since our input strings may contain both ' and ", let's mimic CPython's behavior:
    # CPython uses single quotes unless the string contains a single quote and no double quote.
    # However, for simplicity and correctness, let's just use single quotes and escape single quotes.
    # Actually, let's check if the string contains only single quotes, then use double quotes.
    # But since this is meant to be byte-identical, let me just handle it properly.
    # Let me rebuild using a simpler approach: just construct the full repr-like string.

    # Determine quote style: prefer single, use double if string has single but no double
    has_single = "'" in s
    has_double = '"' in s
    if has_single and not has_double:
        quote = '"'
    else:
        quote = "'"

    result = [quote]
    for c in s:
        o = ord(c)
        if o < 32 or o == 127:
            result.append("\\x%02x" % o)
        elif c == "\\":
            result.append("\\\\")
        elif c == quote:
            if quote == "'":
                result.append("\\'")
            else:
                result.append('\\"')
        elif o > 126:
            if o <= 0xFFFF:
                result.append("\\u%04x" % o)
            else:
                result.append("\\U%08x" % o)
        else:
            result.append(c)
    result.append(quote)
    return "".join(result)

