def manual_repr_str(s):
    if not s:
        return "''"

    # If the string contains only printable ASCII, use single quotes with escaping for ' and backslash
    # CPython's repr uses single quotes unless the string contains a single quote but no double quote
    # Let me implement the full logic

    has_single = "'" in s
    has_double = '"' in s

    # Determine if we need to escape everything (if non-printable or special)
    needs_escapes = False
    use_double = False

    for c in s:
        o = ord(c)
        if o < 32 or o > 126:
            needs_escapes = True
        elif c == "'":
            has_single = True
        elif c == '"':
            has_double = True
        elif c == '\\':
            needs_escapes = True

    # CPython repr logic:
    # Use single quotes if no single quote present, otherwise double quotes
    # But if both are present, use whichever is fewer? No, CPython picks single quotes
    # and escapes the single quotes, OR switches to double quotes.

    # Actually CPython: if the string contains only printable ASCII characters,
    # it uses single quotes unless there's a single quote without a double quote,
    # in which case it uses double quotes.

    if not needs_escapes:
        if has_single and not has_double:
            return '"' + s + '"'
        else:
            escaped = s.replace('\\', '\\\\').replace("'", "\\'")
            return "'" + escaped + "'"
    else:
        # Has non-printable characters, so we need full escaping
        # Build the repr with \xNN, \n, \r, \t, etc.
        result = []
        for c in s:
            o = ord(c)
            if o == 39:  # '
                if has_single and not has_double:
                    result.append("'")
                else:
                    result.append("\\'")
            elif o == 34:  # "
                if has_single and not has_double:
                    result.append('"')
                else:
                    result.append('\\"')
            elif o == 92:  # \
                result.append('\\\\')
            elif o == 10:
                result.append('\\n')
            elif o == 13:
                result.append('\\r')
            elif o == 9:
                result.append('\\t')
            elif 32 <= o <= 126:
                result.append(c)
            else:
                # For non-printable, use \xNN for < 256, \uNNNN for >= 256
                if o < 256:
                    result.append('\\x%02x' % o)
                else:
                    # Try to find surrogate pairs or use \u format
                    # For simplicity and correctness matching CPython:
                    if o < 0x10000:
                        result.append('\\u%04x' % o)
                    else:
                        # Surrogate pair
                        v = o - 0x10000
                        hi = 0xD800 | (v >> 10)
                        lo = 0xDC00 | (v & 0x3FF)
                        result.append('\\u%04x\\u%04x' % (hi, lo))

        body = ''.join(result)
        if has_single and not has_double:
            return '"' + body + '"'
        else:
            return "'" + body + "'"

