def is_seeded_stream(p, prog):
    import ast
    tree = ast.parse(prog)
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name == 'random' and (alias.asname or alias.name) == 'random':
                    pass
        elif isinstance(node, ast.ImportFrom):
            if node.module == 'random':
                for alias in node.names:
                    if alias.name == 'seed' and alias.asname != 'random':
                        return False
        elif isinstance(node, ast.Call):
            func = node.func
            seed_name = None
            if isinstance(func, ast.Attribute):
                if isinstance(func.value, ast.Name) and func.value.id == 'random' and func.attr == 'seed':
                    seed_name = 'seed'
            if seed_name is not None:
                if len(node.args) >= 1:
                    arg = node.args[0]
                    if isinstance(arg, ast.Constant) and arg.value is not None:
                        return True
                    else:
                        return False
    return False

def is_run_specific(p, prog):
    import ast
    tree = ast.parse(prog)
    for node in ast.walk(tree):
        if isinstance(node, ast.Attribute):
            if isinstance(node.value, ast.Name) and node.value.id == 'random' and node.attr == 'random':
                if is_seeded_stream(p, prog):
                    return True
    return False

def is_nondeterministic(p, prog):
    return not is_seeded_stream(p, prog)

def make_E(p, tags=()):
    def _is_seeded(program=p, t=tags):
        return is_seeded_stream(t, program)
    def _is_run_specific(program=p, t=tags):
        return is_run_specific(t, program)
    def _is_nondeterministic(program=p, t=tags):
        return is_nondeterministic(t, program)
    d = {
        '__class__': type('E', (), {'__init__': lambda self, pp, tt=(): setattr(self, 'program', pp), setattr(self, 'tags', tt)}),
        'is_seeded_stream': _is_seeded,
        'is_run_specific': _is_run_specific,
        'is_nondeterministic': _is_nondeterministic,
        'program': p,
        'tags': tags,
    }
    return types.SimpleNamespace(**d) if hasattr(__import__('types'), 'SimpleNamespace') else namespace_factory(p, tags)

import types
def namespace_factory(p, tags):
    ns = types.SimpleNamespace()
    ns.program = p
    ns.tags = tags
    ns.is_seeded_stream = lambda self=ns: is_seeded_stream(tags, p)
    ns.is_run_specific = lambda self=ns: is_run_specific(tags, p)
    ns.is_nondeterministic = lambda self=ns: is_nondeterministic(tags, p)
    return ns

