def _dkeys_repr(d):
    keys = list(d.keys())
    return dict(keys).__repr__()

def _dvals_repr(d):
    vals = list(d.values())
    return list.__repr__(vals)

def _ditems_repr(d):
    items = list(d.items())
    return list(items).__repr__()

def _dicts_like_str(seq):
    # produce str(dict(seq)) — for empty or single key/value case matching dict repr's str form
    if not seq:
        return "{}"
    parts = []
    for k, v in seq:
        ks = str(k)
        vs = str(v)
        if isinstance(k, str) and len(ks) > 1 and ks[0] == "'" and ks[-1] == "'":
            inner = ks[1:-1]
            parts.append(inner + '=' + vs)
        else:
            parts.append(ks + '=' + vs)
    return '{' + ', '.join(parts) + '}'

