def _re_sub(pattern, repl, text):
    # Manually implement the two specific re.sub calls using string operations.

    # Case 1: r"(\w+)@(\w+)" -> r"\2:\1"
    if pattern == r"(\w+)@(\w+)":
        # Find first occurrence of word chars @ word chars
        i = 0
        n = len(text)
        while i < n:
            # find start of \w+
            while i < n and not (text[i].isalpha() or text[i].isdigit() or text[i] == '_'):
                i += 1
            start1 = i
            while i < n and (text[i].isalpha() or text[i].isdigit() or text[i] == '_'):
                i += 1
            end1 = i
            if i < n and text[i] == '@':
                j = i + 1
                while j < n and not (text[j].isalpha() or text[j].isdigit() or text[j] == '_'):
                    j += 1
                start2 = j
                while j < n and (text[j].isalpha() or text[j].isdigit() or text[j] == '_'):
                    j += 1
                end2 = j
                if start2 < end2:
                    group1 = text[start1:end1]
                    group2 = text[start2:end2]
                    replacement = group2 + ':' + group1
                    return text[:start1] + replacement + text[end2:]
        return text

    # Case 2: r"(?P<a>\d+)" -> r"[\g<a>]"
    if pattern == r"(?P<a>\d+)":
        result = []
        i = 0
        n = len(text)
        while i < n:
            if text[i].isdigit():
                j = i
                while j < n and text[j].isdigit():
                    j += 1
                digits = text[i:j]
                result.append('[' + digits + ']')
                i = j
            else:
                result.append(text[i])
                i += 1
        return ''.join(result)

    # Fallback: should not happen for our known cases
    raise ValueError("Unexpected pattern")


