print(_re_sub(r"(?P<a>\d+)", r"[\g<a>]", "n42"))

def sub_pattern(pattern, repl_string, text):
    # Handle the specific patterns and replacements used in the original program

    if pattern == r"(\w+)@(\w+)" and repl_string == r"\2:\1":
        return sub_word_at_word_colon(text)

    elif pattern == r"(?P<a>\d+)" and repl_string == r"[\g<a>]":
        return sub_digits_brackets(text)

    else:
        raise ValueError(f"Unhandled pattern: {pattern} {repl_string}")

def sub_word_at_word_colon(text):
    # Match (\w+)@(\w+) and replace with \2:\1
    i = 0
    result = []
    n = len(text)
    while i < n:
        # Try to match at position i
        j = i
        word1_chars = []
        while j < n and is_word_char(text[j]):
            word1_chars.append(text[j])
            j += 1
        if word1_chars and j < n and text[j] == '@':
            # Check for second word
            k = j + 1
            word2_chars = []
            while k < n and is_word_char(text[k]):
                word2_chars.append(text[k])
                k += 1
            if word2_chars:
                word1 = ''.join(word1_chars)
                word2 = ''.join(word2_chars)
                result.append(f"{word2}:{word1}")
                i = k
                continue
        # No match at this position
        result.append(text[i])
        i += 1
    return ''.join(result)

def is_word_char(c):
    return c.isalnum() or c == '_'

def sub_digits_brackets(text):
    # Match (?P<a>\d+) and replace with [\g<a>]
    i = 0
    result = []
    n = len(text)
    while i < n:
        if text[i].isdigit():
            j = i
            digits = []
            while j < n and text[j].isdigit():
                digits.append(text[j])
                j += 1
            num_str = ''.join(digits)
            result.append(f"[{num_str}]")
            i = j
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

