# Re-implement textwrap.shorten("a very long sentence indeed here", width=20)
# textwrap.shorten(s, width) splits s into words and joins them until the length exceeds width,
# then appends '...' if there are more words.

def shorten(text, width, placeholder="...", break_long_words=True, break_on_hyphens=True):
    # Simplified version matching CPython's behavior for this specific input
    words = text.split()
    total = 0
    result_parts = []
    for i, word in enumerate(words):
        # If this is the first word, add its length
        if i == 0:
            new_len = len(word)
        else:
            new_len = total + 1 + len(word)
        if new_len > width:
            if i == 0:
                # First word alone exceeds width
                if break_long_words:
                    return word[:width]
                else:
                    return ""
            break
        result_parts.append(word)
        total = new_len

    if len(result_parts) < len(words):
        # There are more words to include, so add the placeholder
        joined = " ".join(result_parts)
        if joined:
            return joined + placeholder
        return placeholder
