def _fill(text, width):
    words = text.split()
    lines = []
    current_line = ""
    for word in words:
        if not current_line:
            current_line = word
        elif len(current_line) + 1 + len(word) <= width:
            current_line += " " + word
        else:
            lines.append(current_line)
            current_line = word
    if current_line:
        lines.append(current_line)
    return "\n".join(lines)

def _dedent(text):
    indents = []
    first = True
    for line in text.split('\n'):
        if line.strip():
            i = 0
            while i < len(line) and line[i] == ' ':
                i += 1
            if first:
                indent_len = i
            else:
                indent_len = min(indent_len, i)
            first = False
        else:
            continue
    result_lines = []
    for line in text.split('\n'):
        if line.strip():
            result_lines.append(line[indent_len:])
        else:
            result_lines.append(line)
    return '\n'.join(result_lines)

