import sys


class BadPatternError(Exception):
    """Emulates CPython's sre_constants.error for bad character ranges."""
    pass


def _compile_literal(pattern: str) -> None:
    """Minimal re.compile that raises on an invalid character range like '[a--b]'."""
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '[':
            j = i + 1
            # check leading ^ or ]
            if j < n and pattern[j] in ('^', ']'):
                j += 1
            start_range = True
            prev_char = None
            while j < n:
                ch = pattern[j]
                if ch == ']' and not (prev_char == '\\'):
                    break
                if start_range and ch != ']':
                    # read this token as a single char
                    if ch == '\\' and j + 1 < n:
                        prev_char = pattern[j + 1]
                        j += 2
                    else:
                        prev_char = ch
                        j += 1
                    # after first char, look for '-'
                    if j < n and pattern[j] == '-':
                        # second part of range
                        j += 1
                        if j >= n or pattern[j] == ']':
                            raise BadPatternError("unterminated character set")
                        if pattern[j] == '\\':
                            if j + 1 >= n:
                                raise BadPatternError("bad character range")
                            end_char = pattern[j + 1]
                            j += 2
                        else:
                            end_char = pattern[j]
                            j += 1
                        # compare code points
                        cp_start = ord(prev_char)
                        cp_end = ord(end_char)
                        if cp_start > cp_end:
                            raise BadPatternError(
                                "bad character range"
                            )
                    # else no dash, just skip
                    continue
                else:
                    if ch == '\\':
                        if j + 1 < n:
                            prev_char = pattern[j + 1]
                        else:
                            prev_char = ch
                        j += 2
                    else:
                        prev_char = ch
                        j += 1
            else:
                # no closing ']' found — but for our purposes this is fine;
                # we only need to detect bad ranges
                pass
            i = j + 1
            start_range = False
        else:
            i += 1


for i in range(3):
    try:
        _compile_literal('[a--b]')
        print('ok', i)
    except Exception as e:
        # Format to match the original: type(e).__name__ is 'error' in CPython's re
        # We need byte-identical output. In CPython, re.purge exists and the error
