    if n >= 2 and spec[0] != '<' and spec[0] != '>' and spec[0] != '^' and spec[0] != '=' and \
       spec[1] in '<>^=':
        fill = spec[0]
        align = spec[1]
        i = 2
    elif n >= 1 and spec[0] in '<>^=':
        align = spec[0]
        i = 1

    while i < n:
        c = spec[i]
        if c in '+- ' and not sign:
            sign = c
            i += 1
        elif c == '#' and not alt:
            alt = c
            i += 1
        elif c == '0' and not zero and width == '':
            # This is ambiguous - could be zero padding or part of width
            # Actually, '0' before a digit is zero-padding flag
            zero = c
            i += 1
        elif c in ',_':
            grouping = c
            i += 1
        elif c == '.':
            i += 1
            while i < n and spec[i].isdigit():
                precision += spec[i]
                i += 1
            break
        elif c.isdigit() and width == '':
            while i < n and spec[i].isdigit():
                width += spec[i]
                i += 1
        elif c.isalpha():
            typ = c
            i += 1
            break
        else:
            raise ValueError("Invalid format specification: %r" % spec)

