def deterministic_set_to_list(elements):
    """Convert a set of elements to a sorted list for deterministic output."""
    if not elements:
        return []
    try:
        # Sort all together - works for numbers, strings, etc.
        # We need to handle mixed types by converting to a sortable form
        return sorted(list(elements), key=lambda x: (type(x).__name__, str(x)))
    except TypeError:
        return sorted(list(elements))

