def _eval(expr):
    # Simple safe eval for the specific expressions used
    # They are of the form: re.func(args) or re.compile(...) etc.
    import ast
    tree = ast.parse(expr, mode='eval')
    if not isinstance(tree.body, ast.Call):
        raise ValueError("not a call")
    node = tree.body
    # Resolve function
    func = node.func
    if not (isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name) and func.value.id == 're'):
        raise ValueError("only re.* calls supported")
    fname = func.attr
    args = []
    kw = {}
    for a in node.args:
        args.append(_eval_node(a))
    for k in node.keywords:
        kw[k.arg] = _eval_node(k.value)
    f = getattr(re, fname)
    return f(*args, **kw)

def _eval_node(node):
    import ast
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.Str):
        return node.s
    if isinstance(node, ast.Bytes):
        return node.s
    if isinstance(node, ast.Num):
        return node.n
    if isinstance(node, ast.NameConstant):
        return node.value
    if isinstance(node, ast.Name):
        id_ = node.id
        if id_ == 're':
            return re
