        globals_map = {'re': re}
        if id_ in globals_map:
            return globals_map[id_]
        raise NameError(id_)
    if isinstance(node, ast.Attribute):
        if isinstance(node.value, ast.Name) and node.value.id == 're':
            return getattr(re, node.attr)
        raise ValueError("unsupported attribute")
    if isinstance(node, ast.Tuple):
        return tuple(_eval_node(el) for el in node.elts)
    if isinstance(node, ast.List):
        return [_eval_node(el) for el in node.elts]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
        return not _eval_node(node.operand)
    raise ValueError("unsupported expression")

