# Build a restricted eval that can call re functions only.
def _restricted_eval(expr):
    # expr is expected to be of form: re.func(args...) or re.finditer(...) etc.
    # We'll parse the function name and arguments safely.
    # Use ast module for safe parsing? No, ast is in stdlib but let's use a simpler approach.
    # Actually, we need to evaluate Python expressions like re.findall('[]a]', 'xa]')
    # These involve string literals, function calls on re module.
    # Safe approach: use ast.literal_eval won't work for function calls.
    # Let's use a whitelisted eval with a restricted globals/locals.

    import ast

    code = compile(expr, '<expr>', 'eval')

    # Check if the AST is safe - only allows:
    # - Call nodes where func is Attribute (re.something) or Name in whitelist
    # - String, Number, List, Tuple literals
    # - None, True, False
    def check_node(node):
        if isinstance(node, ast.Expression):
            check_node(node.body)
        elif isinstance(node, ast.Call):
            # Function must be re.<something> or a whitelisted name
            if isinstance(node.func, ast.Attribute):
                if not isinstance(node.func.value, ast.Name):
                    raise Exception("bad call")
                if node.func.value.id != 're':
                    raise Exception("bad call")
            elif isinstance(node.func, ast.Name):
                pass  # could be something else, but our exprs should be re.xxx
            else:
                raise Exception("bad call")
            for arg in node.args:
                check_node(arg)
            for kw in node.keywords:
                check_node(kw.value)
        elif isinstance(node, (ast.Str, ast.Num, ast.List, ast.Tuple)):
            pass
        elif isinstance(node, ast.NameConstant):
            pass
        elif isinstance(node, ast.Constant):
            pass
        elif isinstance(node, ast.Attribute):
            pass
        elif isinstance(node, ast.Name):
            pass
        else:
            raise Exception("unsafe expression")

    try:
        tree = ast.parse(expr, mode='eval')
        check_node(tree)
    except SyntaxError:
        raise

    # Now we can safely eval with restricted namespace
    g = {'re': re}
    l = {}
    return eval(code, g, l)


