    if expr.startswith("r'") and expr.endswith("'"):
        return ('rawstr', expr[2:-1])

    if expr.startswith('b\'') and expr.endswith('\''):
        return ('bytes', expr[2:-1])

    # Simple integer
    try:
        return ('int', int(expr))
    except ValueError:
        pass

